from conftest import fill, get_path  # noqa: F401


def test_melon_matches(client):
    r = client.request('GET', '/api/search', params={'q': 'melon'})
    assert r.status_code == 200, r.text
    body = r.json()
    assert get_path(body, 'results') == ['melon', 'watermelon']


def test_server_error_is_a_500(client):
    r = client.request('GET', '/api/search', params={'q': 'error'})
    assert r.status_code == 500, r.text
